<?php
require __DIR__.'/_admin.php';
$pdo=db();$error='';$id=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT)?:0;
if($_SERVER['REQUEST_METHOD']==='POST'){
 admin_validate_csrf();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);
 try {
 if($action==='delete'){$stmt=$pdo->prepare('UPDATE products SET active=0 WHERE id=?');$stmt->execute([$id]);flash_set('Product hidden from public catalogue.');header('Location: products.php');exit;}
 $slug=trim((string)($_POST['slug']??''));$en=trim((string)($_POST['name_en']??''));$si=trim((string)($_POST['name_si']??''));$cat=(string)($_POST['category']??'');$de=trim((string)($_POST['description_en']??''));$ds=trim((string)($_POST['description_si']??''));$img=trim((string)($_POST['image']??''));$featured=isset($_POST['featured'])?1:0;$active=isset($_POST['active'])?1:0;$order=(int)($_POST['sort_order']??100);
 if(!preg_match('/^[a-z0-9][a-z0-9-]{1,145}$/',$slug)||$en===''||$si===''||!in_array($cat,['films','bags','food','protective'],true)||$de===''||$ds==='')throw new RuntimeException('All bilingual product fields and a valid slug/category are required.');
 if(mb_strlen($en)>200||mb_strlen($si)>200)throw new RuntimeException('Product name must be below 200 characters.');
 if(!preg_match('~^assets/(images/products/[a-z0-9-]+\.svg|uploads/[a-zA-Z0-9_-]+\.(jpg|jpeg|png|webp))$~',$img))throw new RuntimeException('Choose a safe product image path, or upload an image below.');
 if(!empty($_FILES['upload']['name'])){
  if($_FILES['upload']['error']!==UPLOAD_ERR_OK||$_FILES['upload']['size']>3*1024*1024)throw new RuntimeException('Image upload failed or exceeds 3 MB.');
  $m=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['upload']['tmp_name']);$mime=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($mime[$m]))throw new RuntimeException('Only JPG, PNG and WEBP images are supported.');
  $name=bin2hex(random_bytes(16)).'.'.$mime[$m];$dest=__DIR__.'/../assets/uploads/'.$name;if(!move_uploaded_file($_FILES['upload']['tmp_name'],$dest))throw new RuntimeException('Image could not be saved.');$img='assets/uploads/'.$name;
 }
 if($id){$q=$pdo->prepare('UPDATE products SET slug=?,name_en=?,name_si=?,category=?,description_en=?,description_si=?,image=?,featured=?,active=?,sort_order=? WHERE id=?');$q->execute([$slug,$en,$si,$cat,$de,$ds,$img,$featured,$active,$order,$id]);}
 else{$q=$pdo->prepare('INSERT INTO products (slug,name_en,name_si,category,description_en,description_si,image,featured,active,sort_order) VALUES (?,?,?,?,?,?,?,?,?,?)');$q->execute([$slug,$en,$si,$cat,$de,$ds,$img,$featured,$active,$order]);}
 flash_set($id?'Product updated.':'Product created.');header('Location: products.php');exit;
 }catch(Throwable $err){$error=$err->getMessage();}
}
$edit=null;if($id){$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);$edit=$q->fetch();}
$new=isset($_GET['new']);
$all=$pdo->query('SELECT * FROM products ORDER BY sort_order ASC,id ASC')->fetchAll();
admin_header('Manage Products');flash_show();if($error)echo '<div class="error">'.e($error).'</div>';
?><div class="panel"><div class="panel-header"><h2><?=($edit||$new)?($edit?'Edit Product':'Add New Product'):'Product Catalogue'?></h2><a class="admin-btn small" href="<?=($edit||$new)?'products.php':'products.php?new=1'?>"><?=($edit||$new)?'← Back':'Add Product +'?></a></div>
<?php if($edit||$new):$d=$edit?:['id'=>0,'slug'=>'','name_en'=>'','name_si'=>'','category'=>'bags','description_en'=>'','description_si'=>'','image'=>'assets/images/products/shopping-bags.svg','featured'=>0,'active'=>1,'sort_order'=>100];?>
<form method="post" enctype="multipart/form-data" class="admin-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e((string)$d['id'])?>"><input type="hidden" name="action" value="save"><div class="admin-form-grid"><label>Product slug <small>(lowercase letters and hyphens)</small><input name="slug" value="<?=e($d['slug'])?>" required></label><label>Category<select name="category"><?php foreach(['films'=>'Polythene & Films','bags'=>'Bags & Pouches','food'=>'Food Packaging','protective'=>'Protective & General'] as $key=>$label):?><option value="<?=e($key)?>" <?=($d['category']===$key?'selected':'')?>><?=e($label)?></option><?php endforeach;?></select></label><label>English Name<input name="name_en" required value="<?=e($d['name_en'])?>"></label><label>Sinhala Name<input name="name_si" required value="<?=e($d['name_si'])?>"></label><label class="full">English Description<textarea name="description_en" rows="3" required><?=e($d['description_en'])?></textarea></label><label class="full">Sinhala Description<textarea name="description_si" rows="3" required><?=e($d['description_si'])?></textarea></label><label>Image path<input name="image" value="<?=e($d['image'])?>" required><small>Built-in SVG path, or an uploaded image path.</small></label><label>Upload new product image<input type="file" name="upload" accept=".png,.jpg,.jpeg,.webp"><small>Optional; JPG/PNG/WEBP ≤ 3MB</small></label><label>Display order<input name="sort_order" type="number" value="<?=e((string)$d['sort_order'])?>"></label><div class="admin-flags"><label><input type="checkbox" name="featured" value="1" <?=$d['featured']?'checked':''?>> Featured on home page</label><label><input type="checkbox" name="active" value="1" <?=$d['active']?'checked':''?>> Visible in catalogue</label></div></div><button class="admin-btn" type="submit">Save Product →</button></form>
<?php else:?><div class="table-scroll"><table><thead><tr><th>Image</th><th>Product</th><th>Category</th><th>Featured</th><th>Visible</th><th>Actions</th></tr></thead><tbody><?php foreach($all as $d):?><tr><td><img class="tiny-product" src="../<?=e($d['image'])?>" alt=""></td><td><strong><?=e($d['name_en'])?></strong><small><?=e($d['name_si'])?></small></td><td><?=e($d['category'])?></td><td><?=$d['featured']?'✓':'—'?></td><td><?=$d['active']?'✓':'Hidden'?></td><td><a href="products.php?edit=<?=(int)$d['id']?>" class="action-link">Edit ↗</a> <?php if($d['active']):?><form method="post" class="inline" onsubmit="return confirm('Hide this product from the catalogue?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$d['id']?>"><input type="hidden" name="action" value="delete"><button type="submit" class="inline-danger">Hide</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php admin_footer();?>
